Given a square matrix mat[][], swap the elements of its major and minor diagonals.Major Diagonal (Primary/Main Diagonal): Elements that run from the top-left corner to the bottom-right corner of the matrix where the row and column indices are the same.Minor Diagonal (Secondary Diagonal): Elements that run from the top-right corner to the bottom-left corner where the sum of row and column indices equals one less than the matrix size.Examples: Input: mat[][] = [[0, 1, 2],                            [3, 4, 5],                            [6, 7, 8]]Output : [[2, 1, 0],                 [3, 4, 5],                 [8, 7, 6]]Explanation: Major Diagonal  = [0, 4, 8], Minor Diagonal = [2, 4, 6]. We are required to swap the diagonal elements of same row, thus after doing so, major diagonal will become minor and vice-versa.Input: mat[][] = [[2, 3],                            [5, 4]]Output : [[3, 2],                 [4, 5]]Explanation: Major Diagonal  = [2, 4], Minor Diagonal = [3, 5]. We are required to swap the diagonal elements of same row, thus after doing so, major diagonal will become minor and vice-versaTry It YourselfTable of Content[Approach 1] Diagonal Buffer Swap - O(n) Time and O(n) Space[Approach 2] Two-Pointer Diagonal Swap - O(n)  Time and O(1) Time[Approach 1] Diagonal Buffer Swap - O(n) Time and O(n) SpaceThe idea is to store the elements of the major and minor diagonals separately to avoid overwriting, then swap them by placing each into the other's position.
            C++

    #include <iostream>
#include <vector>
using namespace std;

void swapDiagonal(vector<vector<int>>& mat) {
    int size = mat.size();
    vector<int> majorDia(size), minorDia(size);

    // Store major and minor diagonal elements
    for (int i = 0; i < size; i++) {
        majorDia[i] = mat[i][i];
        minorDia[i] = mat[i][size - i - 1];
    }

    // Swap the diagonals by placing stored values
    for (int i = 0; i < size; i++) {
        mat[i][i] = minorDia[i];
        mat[i][size - i - 1] = majorDia[i];
    }
}

int main() {
    vector<vector<int>> mat = {
        {0, 1, 2},
        {3, 4, 5},
        {6, 7, 8}
    };

    swapDiagonal(mat);
    for (const auto& row : mat) {
        for (int val : row)
            cout << val << " ";
        cout << endl;
    }

    return 0;
}


