[Approach 2] Two-Pointer Diagonal Swap - O(n)  Time and O(1) TimeIn a square matrix, the major diagonal consists of elements where the row and column indices are equal (i.e., mat[i][i]), while the minor diagonal has elements where the sum of row and column indices equals one less than the matrix size (i.e., mat[i][mat.size() - 1 - i]).To swap these diagonals, iterate through each row using a two-pointer like logic: one pointer accesses the major diagonal element, and the other accesses the minor diagonal element. Swap these elements in each row.  
            C++

    #include <iostream>
#include <vector>
using namespace std;

void swapDiagonal(vector<vector<int>>& mat) {

    int n = mat.size();
    for (int i = 0; i < n; i++) {

        // swap major and minor diagonal elements.
        swap(mat[i][i], mat[i][n - i - 1]);
    }
}


int main() {

    vector<vector<int>> mat = 
                       {{0, 1, 2},
                        {3, 4, 5},
                        {6, 7, 8}};

    swapDiagonal(mat);
    for (int i = 0; i < mat.size(); i++) {
        for (int j = 0; j < mat.size(); j++)
            cout << mat[i][j] << " ";
        cout << endl;
    }

    return 0;
}


